llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Limonin, a complex polycyclic triterpenoid lactone with poor aqueous solubility, shows low blood concentrations and poor oral bioavailability in humans; its rigid polycyclic lactone character and lipophilicity transfer weakly to the query's similar lactone-rich scaffold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Fluticasone, a lipophilic fused-ring corticosteroid, has negligible (<1%) absolute oral bioavailability via gastrointestinal absorption due to poor solubility and first-pass metabolism, providing affirmative threshold-relevant evidence that a highly lipophilic, poorly water-soluble fused-ring molecule can fall far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "EM574, a lactone-containing macrolide, has an estimated oral bioavailability of about 2% in humans due to very high oral clearance; its lactone-rich, lipophilic character and extensive first-pass liability support low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Artemisinin, a polycyclic sesquiterpene lactone natural product, has low oral bioavailability in healthy volunteers and malaria patients; the query shares a rigid lactone framework, and this direct human low-F evidence transfers weakly but affirmatively.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Artesunate, an artemisinin derivative, achieved 61% absolute oral bioavailability in Thai patients, showing that some lactone-containing natural products can exceed 20%; however, the query lacks the solubilizing carboxylate group, and this evidence is only weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Dexamethasone, a fused-ring corticosteroid, has about 58.5% absolute oral bioavailability in humans, indicating that rigid lipophilic fused-ring steroids can be well absorbed; but the query's multiple lactones and tert-butyl group differ substantially from a typical corticosteroid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Prediction is low: the query's complex polycyclic lactone architecture, tert-butyl group, and multiple ester oxygens suggest poor aqueous solubility and high first-pass/efflux liability. The most transferable experimental evidence—limonin, fluticasone, EM574, and artemisinin—affirmatively shows low or poor oral bioavailability, while high-F analogues are structurally distant and weakly transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query or a close analogue.",
    "Morgan similarities to all evidence molecules are low (<0.2), limiting transferability.",
    "Several qualitative 'low' or 'poor' bioavailability records do not specify whether F is below the 20% threshold.",
    "Lack of human pharmacokinetic data for triptolide-like or limonin-like scaffolds with tert-butyl substitution."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

